('values:block_content:2','O:40:\"Drupal\\block_content\\Entity\\BlockContent\":32:{s:15:\"\0*\0entityTypeId\";s:13:\"block_content\";s:15:\"\0*\0enforceIsNew\";N;s:12:\"\0*\0typedData\";N;s:17:\"\0*\0originalEntity\";N;s:16:\"\0*\0cacheContexts\";a:0:{}s:12:\"\0*\0cacheTags\";a:0:{}s:14:\"\0*\0cacheMaxAge\";i:-1;s:14:\"\0*\0_serviceIds\";a:0:{}s:18:\"\0*\0_entityStorages\";a:0:{}s:9:\"\0*\0values\";a:17:{s:2:\"id\";a:1:{s:9:\"x-default\";s:1:\"2\";}s:11:\"revision_id\";a:1:{s:9:\"x-default\";s:1:\"2\";}s:4:\"type\";a:1:{s:9:\"x-default\";s:13:\"homepage_hero\";}s:4:\"uuid\";a:1:{s:9:\"x-default\";s:36:\"ff091d60-d75d-468d-9d37-38d0fb018474\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:13:\"revision_user\";a:1:{s:9:\"x-default\";N;}s:16:\"revision_created\";a:1:{s:9:\"x-default\";s:10:\"1789111231\";}s:12:\"revision_log\";a:1:{s:9:\"x-default\";N;}s:16:\"revision_default\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:17:\"isDefaultRevision\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:6:\"status\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:4:\"info\";a:1:{s:9:\"x-default\";s:18:\"Main Homepage Hero\";}s:7:\"changed\";a:1:{s:9:\"x-default\";s:10:\"1789189717\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:29:\"revision_translation_affected\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:8:\"reusable\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:10:\"field_body\";a:1:{s:9:\"x-default\";a:1:{i:0;a:2:{s:5:\"value\";s:1816:\"<section class=\"pcf-hero\" aria-label=\"Homepage hero\">\r\n  <video\r\n    class=\"pcf-hero__video\"\r\n    autoplay muted loop playsinline\r\n    id=\"pcf-hero-video\">\r\n    <source src=\"/sites/default/files/hero-video.mp4\" type=\"video/mp4\">\r\n  </video>\r\n  <div class=\"pcf-hero__overlay\"></div>\r\n  <div class=\"pcf-hero__content\">\r\n    <h1>Protecting policyholders when insurers fail</h1>\r\n    <p class=\"pcf-hero__subtitle\">Upholding public confidence in the insurance sector through timely compensation of claimants and prompt resolution of insurers.</p>\r\n    <div class=\"pcf-hero__ctas\">\r\n      <a href=\"/node/add/page\" class=\"pcf-btn pcf-btn--primary\">Check Compensation Status</a>\r\n      <a href=\"/node/add/page\" class=\"pcf-btn pcf-btn--secondary\">Report Corruption</a>\r\n    </div>\r\n  </div>\r\n  <button type=\"button\" class=\"pcf-hero__pause\" id=\"pcf-hero-pause\" aria-pressed=\"false\">\r\n    <span class=\"pcf-hero__pause-icon\" aria-hidden=\"true\">❚❚</span>\r\n    <span class=\"pcf-hero__pause-label\">Pause</span>\r\n  </button>\r\n</section>\r\n\r\n<script>\r\n(function () {\r\n  var video = document.getElementById(\'pcf-hero-video\');\r\n  var btn = document.getElementById(\'pcf-hero-pause\');\r\n  var icon = btn.querySelector(\'.pcf-hero__pause-icon\');\r\n  var label = btn.querySelector(\'.pcf-hero__pause-label\');\r\n  if (window.matchMedia(\'(prefers-reduced-motion: reduce)\').matches) {\r\n    video.pause(); btn.setAttribute(\'aria-pressed\', \'true\'); icon.textContent = \'►\'; label.textContent = \'Play\';\r\n  }\r\n  btn.addEventListener(\'click\', function () {\r\n    if (video.paused) { video.play(); btn.setAttribute(\'aria-pressed\', \'false\'); icon.textContent = \'❚❚\'; label.textContent = \'Pause\'; }\r\n    else { video.pause(); btn.setAttribute(\'aria-pressed\', \'true\'); icon.textContent = \'►\'; label.textContent = \'Play\'; }\r\n  });\r\n})();\r\n</script>\";s:6:\"format\";s:9:\"full_html\";}}}}s:9:\"\0*\0fields\";a:0:{}s:19:\"\0*\0fieldDefinitions\";N;s:12:\"\0*\0languages\";N;s:14:\"\0*\0langcodeKey\";s:8:\"langcode\";s:21:\"\0*\0defaultLangcodeKey\";s:16:\"default_langcode\";s:17:\"\0*\0activeLangcode\";s:9:\"x-default\";s:28:\"\0*\0enforceDefaultTranslation\";N;s:18:\"\0*\0defaultLangcode\";s:2:\"en\";s:15:\"\0*\0translations\";a:1:{s:9:\"x-default\";a:1:{s:6:\"status\";i:1;}}s:24:\"\0*\0translationInitialize\";b:0;s:14:\"\0*\0newRevision\";b:0;s:20:\"\0*\0isDefaultRevision\";s:1:\"1\";s:13:\"\0*\0entityKeys\";a:4:{s:6:\"bundle\";s:13:\"homepage_hero\";s:2