('values:block_content:4','O:40:\"Drupal\\block_content\\Entity\\BlockContent\":32:{s:15:\"\0*\0entityTypeId\";s:13:\"block_content\";s:15:\"\0*\0enforceIsNew\";N;s:12:\"\0*\0typedData\";N;s:17:\"\0*\0originalEntity\";N;s:16:\"\0*\0cacheContexts\";a:0:{}s:12:\"\0*\0cacheTags\";a:0:{}s:14:\"\0*\0cacheMaxAge\";i:-1;s:14:\"\0*\0_serviceIds\";a:0:{}s:18:\"\0*\0_entityStorages\";a:0:{}s:9:\"\0*\0values\";a:17:{s:2:\"id\";a:1:{s:9:\"x-default\";s:1:\"4\";}s:11:\"revision_id\";a:1:{s:9:\"x-default\";s:1:\"4\";}s:4:\"type\";a:1:{s:9:\"x-default\";s:13:\"homepage_hero\";}s:4:\"uuid\";a:1:{s:9:\"x-default\";s:36:\"a09fdded-e69e-4ba0-b996-430edbbf9c24\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:13:\"revision_user\";a:1:{s:9:\"x-default\";N;}s:16:\"revision_created\";a:1:{s:9:\"x-default\";s:10:\"1789194305\";}s:12:\"revision_log\";a:1:{s:9:\"x-default\";N;}s:16:\"revision_default\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:17:\"isDefaultRevision\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:6:\"status\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:4:\"info\";a:1:{s:9:\"x-default\";s:14:\"Homepage Stats\";}s:7:\"changed\";a:1:{s:9:\"x-default\";s:10:\"1789194305\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:29:\"revision_translation_affected\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:8:\"reusable\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:10:\"field_body\";a:1:{s:9:\"x-default\";a:1:{i:0;a:2:{s:5:\"value\";s:3000:\"<section class=\"pcf-stats\" style=\"background-image: url(\'/sites/default/files/stats-photo.jpg\');\">\r\n  <div class=\"pcf-stats__overlay\"></div>\r\n  <div class=\"pcf-stats__inner\">\r\n    <div class=\"pcf-stats__intro\">\r\n      <h2>Our impact so far</h2>\r\n      <p>Real outcomes for real Kenyan policyholders</p>\r\n    </div>\r\n    <div class=\"pcf-stats__grid\">\r\n      <div class=\"pcf-stat\">\r\n        <span class=\"pcf-stat__number\" data-target=\"2146\" data-decimals=\"0\" data-prefix=\"\" data-suffix=\"\">0</span>\r\n        <span class=\"pcf-stat__label\">Claims settled</span>\r\n      </div>\r\n      <div class=\"pcf-stat\">\r\n        <span class=\"pcf-stat__number\" data-target=\"390.8\" data-decimals=\"1\" data-prefix=\"KSh \" data-suffix=\"M\">0</span>\r\n        <span class=\"pcf-stat__label\">Paid in compensation</span>\r\n      </div>\r\n      <div class=\"pcf-stat\">\r\n        <span class=\"pcf-stat__number\" data-target=\"8\" data-decimals=\"0\" data-prefix=\"\" data-suffix=\"\">0</span>\r\n        <span class=\"pcf-stat__label\">Insurers resolved</span>\r\n      </div>\r\n      <div class=\"pcf-stat\">\r\n        <span class=\"pcf-stat__number\" data-target=\"14\" data-decimals=\"0\" data-prefix=\"\" data-suffix=\"\">0</span>\r\n        <span class=\"pcf-stat__label\">Counties reached through PCFMtaani</span>\r\n      </div>\r\n    </div>\r\n    <p class=\"pcf-stats__note\">Figures as of March 31, 2026</p>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n(function () {\r\n  var counters = document.querySelectorAll(\'.pcf-stat__number\');\r\n  var animated = false;\r\n  function animateCounters() {\r\n    if (animated) return;\r\n    animated = true;\r\n    counters.forEach(function (el) {\r\n      var target = parseFloat(el.getAttribute(\'data-target\'));\r\n      var decimals = parseInt(el.getAttribute(\'data-decimals\'), 10) || 0;\r\n      var prefix = el.getAttribute(\'data-prefix\') || \'\';\r\n      var suffix = el.getAttribute(\'data-suffix\') || \'\';\r\n      var duration = 1600;\r\n      var startTime = null;\r\n      function step(timestamp) {\r\n        if (!startTime) startTime = timestamp;\r\n        var progress = Math.min((timestamp - startTime) / duration, 1);\r\n        var eased = 1 - Math.pow(1 - progress, 3);\r\n        var current = target * eased;\r\n        var formatted = decimals > 0 ? current.toFixed(decimals) : Math.floor(current).toLocaleString();\r\n        el.textContent = prefix + formatted + suffix;\r\n        if (progress < 1) { requestAnimationFrame(step); }\r\n        else { var finalFormatted = decimals > 0 ? target.toFixed(decimals) : target.toLocaleString(); el.textContent = prefix + finalFormatted + suffix; }\r\n      }\r\n      requestAnimationFrame(step);\r\n    });\r\n  }\r\n  var section = document.querySelector(\'.pcf-stats\');\r\n  if (section && \'IntersectionObserver\' in window) {\r\n    var observer = new IntersectionObserver(function (entries) {\r\n      entries.forEach(function (entry) { if (entry.isIntersecting) { animateCounters(); observer.disconnect(); } });\r\n    }, { threshold: 0.3 });\r\n    observer.observe(section);\r\n  } else { animateCounters(); }\r\n})();\r\n</script>\";s:6:\"format\";s:9:\"full_html\";}}}}s:9:\"\0*\0fields\";a:0:{}s:19:\"\0*\0fieldDefinitions\";N;s:12:\"\0*\0languages\";N;s:14:\"\0*\0langcodeKey\";s:8:\"langcode\";s:21:\"\0*\0defaultLangcodeKey\";s:16:\"default_langcode\";s:17:\"\0*\0activeLangcode\";s:9:\"x-default\";s:28:\"\0*\0enforceDefaultTranslation\";N;s:18:\"\0*\0defaultLangcode\";s:2:\"en\";s:15:\"\0*\0translations\";a:1:{s:9:\"x-default\";a:1:{s:6:\"status\";i:1;}}s:24:\"\0*\0translationInitialize\";b:0;s:14:\"\0*\0newRevision\";b:0;s:20:\"\0*\0isDefaultRevision\";s:1:\"1\";s:13:\"\0*\0entityKeys\";a:4:{s:6:\"bundle\";s:13:\"homepage_hero\";s:2:\"id\";s:1:\"4\";s:8:\"revision\";s:1:\"4\";s:4:\"uuid\";s:36:\"a09fdded-e69e-4ba0-b996-430edbbf9c24\";}s:25:\"\0*\0translatableEntityKeys\";a:5:{s:5:\"label\";a:1:{s:9:\"x-default\";s:14:\"Homepage Stats\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:9:\"published\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:29:\"revision_translation_affected\";a:1:{s:9:\"x-default\";s:1:\"1\";}}s:12:\"\0*\0validated\";b:0;s:21:\"\0*\0validationRequired\";b:0;s:19:\"\0*\0loadedRevisionId\";s:1:\"4\";s:33:\"\0*\0revisionTranslationAffectedKey\";s:29:\"revision_translation_affected\";s:37:\"\0*\0enforceRevisionTranslationAffected\";a:0:{}s:12:\"\0*\0isSyncing\";b:0;s:8:\"\0*\0theme\";N