('values:node:5','O:23:\"Drupal\\node\\Entity\\Node\":31:{s:15:\"\0*\0entityTypeId\";s:4:\"node\";s:15:\"\0*\0enforceIsNew\";N;s:12:\"\0*\0typedData\";N;s:17:\"\0*\0originalEntity\";N;s:16:\"\0*\0cacheContexts\";a:0:{}s:12:\"\0*\0cacheTags\";a:0:{}s:14:\"\0*\0cacheMaxAge\";i:-1;s:14:\"\0*\0_serviceIds\";a:0:{}s:18:\"\0*\0_entityStorages\";a:0:{}s:9:\"\0*\0values\";a:26:{s:3:\"nid\";a:1:{s:9:\"x-default\";s:1:\"5\";}s:3:\"vid\";a:1:{s:9:\"x-default\";s:1:\"9\";}s:4:\"type\";a:1:{s:9:\"x-default\";s:4:\"page\";}s:4:\"uuid\";a:1:{s:9:\"x-default\";s:36:\"dbb95ac2-7fde-45c1-9d25-f76c278a2565\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:12:\"revision_uid\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:18:\"revision_timestamp\";a:1:{s:9:\"x-default\";s:10:\"1789196550\";}s:12:\"revision_log\";a:1:{s:9:\"x-default\";N;}s:16:\"revision_default\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:17:\"isDefaultRevision\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:6:\"status\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:3:\"uid\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:5:\"title\";a:1:{s:9:\"x-default\";s:12:\"Compensation\";}s:7:\"created\";a:1:{s:9:\"x-default\";s:10:\"1789195854\";}s:7:\"changed\";a:1:{s:9:\"x-default\";s:10:\"1789196550\";}s:7:\"promote\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:6:\"sticky\";a:1:{s:9:\"x-default\";s:1:\"0\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:29:\"revision_translation_affected\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:10:\"publish_on\";a:1:{s:9:\"x-default\";N;}s:12:\"unpublish_on\";a:1:{s:9:\"x-default\";N;}s:13:\"publish_state\";a:1:{s:9:\"x-default\";N;}s:15:\"unpublish_state\";a:1:{s:9:\"x-default\";N;}s:7:\"deleted\";a:1:{s:9:\"x-default\";a:0:{}}s:13:\"field_content\";a:1:{s:9:\"x-default\";a:1:{i:0;a:2:{s:5:\"value\";s:2244:\"<section class=\"pcf-page-hero\">\r\n  <div class=\"pcf-page-hero__inner\">\r\n    <div class=\"pcf-page-hero__breadcrumb\"><a href=\"/\">Home</a> / What We Do / Compensation</div>\r\n    <h1>Compensation</h1>\r\n    <p>Timely payouts to policyholders and claimants of insurers placed under statutory management or whose licence has been cancelled.</p>\r\n  </div>\r\n</section>\r\n<div class=\"pcf-page-content\">\r\n  <div class=\"pcf-page-main\">\r\n    <h2>How compensation works</h2>\r\n    <p>The Fund covers claims arising from all insurance policies issued in Kenya. Under Section 179 of the Insurance Act and the Policyholders Compensation Fund Regulations 2010, PCF pays compensation to policyholders and claimants of an authorised insurer once it has been placed under statutory management or its licence cancelled.</p>\r\n    <h2>Eligibility exceptions</h2>\r\n    <p>Not every claim qualifies. The Fund does not compensate:</p>\r\n    <ul>\r\n      <li>Claims made more than two years after the date of insolvency of the insurer</li>\r\n      <li>Claims arising from policies issued before the Fund commenced operations</li>\r\n      <li>Claims where liability is duplicated by another authorised insurer that is not insolvent</li>\r\n      <li>Claims relating to incidents occurring before a statutory manager\'s appointment date</li>\r\n    </ul>\r\n    <h2>How to claim</h2>\r\n    <ol>\r\n      <li>Visit the PCF Claims Portal via www.pcf.go.ke</li>\r\n      <li>Register an account on the portal</li>\r\n      <li>Complete the online claim form with accurate details</li>\r\n      <li>Attach all required supporting documents</li>\r\n      <li>Submit for verification, approval, and processing</li>\r\n    </ol>\r\n  </div>\r\n  <aside class=\"pcf-page-sidebar\">\r\n    <div class=\"pcf-info-box\">\r\n      <h3>Quick facts</h3>\r\n      <dl>\r\n        <dt>Maximum payout</dt><dd>KSh 500,000 per claim (Gazette Notice No. 971, 23 Jan 2026)</dd>\r\n        <dt>Claim window</dt><dd>Two years from date of publication of the relevant notice</dd>\r\n        <dt>Legal basis</dt><dd>Section 179, Insurance Act (Cap 487)</dd>\r\n      </dl>\r\n    </div>\r\n    <div class=\"pcf-cta-box\"><p>Ready to start your claim?</p><a href=\"/node/add/page\" class=\"pcf-btn pcf-btn--primary\">File a Claim</a></div>\r\n  </aside>\r\n</div>\";s:6:\"format\";s:9:\"full_html\";}}}s:17:\"field_description\";a:1:{s:9:\"x-default\";a:1:{i:0;a:1:{s:5:\"value\";s:12:\"Compensation\";}}}}s:9:\"\0*\0fields\";a:0:{}s:19:\"\0*\0fieldDefinitions\";N;s:12:\"\0*\0languages\";N;s:14:\"\0*\0langcodeKey\";s:8:\"langcode\";s:21:\"\0*\0defaultLangcodeKey\";s:16:\"default_langcode\";s:17:\"\0*\0activeLangcode\";s:9:\"x-default\";s:28:\"\0*\0enforceDefaultTranslation\";N;s:18:\"\0*\0defaultLangcode\";s:2:\"en\";s:15:\"\0*\0translations\";a:1:{s:9:\"x-default\";a:1:{s:6:\"status\";i:1;}}s:24:\"\0*\0translationInitialize\";b:0;s:14:\"\0*\0newRevision\";b:0;s:20:\"\0*\0isDefaultRevision\";s:1:\"1\";s:13:\"\0*\0entityKeys\";a:4:{s:6:\"bundle\";s:4:\"page\";s:2:\"id\";s:1:\"5\";s:8:\"revision\";s:1:\"9\";s:4:\"uuid\";s:36:\"dbb95ac2-7fde-45c1-9d25-f76c278a2565\";}s:25:\"\0*\0translatableEntityKeys\";a:8:{s:5:\"label\";a:1:{s:9:\"x-default\";s:12:\"Compensation\";}s:8:\"langcode\";a:1:{s:9:\"x-default\";s:2:\"en\";}s:6:\"status\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:9:\"published\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:3:\"uid\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:5:\"owner\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:16:\"default_langcode\";a:1:{s:9:\"x-default\";s:1:\"1\";}s:29:\"revision_translation_affected\";a:1:{s:9:\"x-default\";s:1:\"1\";}}s:12:\"\0*\0validated\";b:0;s:21:\"\0*\0validationRequired\";b:0;s:19:\"\0*\0loadedRevisionId\";s:1:\"9\";s:33:\"\0*\0revisionTranslationAffectedKey\";s:29:\"revision_translation_affected\";s:37:\"\0*\0enforceRevisionTranslationAffected\";a:0:{}s:12:\"\0*\0isSyncing\";b:0;s:10:\"in_preview\";N;}',-1,1789286244.087,1,'entity_field_info','0'),
