('entity_view:block:pcf_theme_homepageservices_2:[languages:language_interface]=en:[route.name.is_layout_builder_ui]=is_layout_builder_ui.1:[theme]=pcf_theme:[user.permissions]=a89e24af461adc3524902f5a2d219617cd0066ced07fd34ced61ca4b5ef9dcd5','a:3:{s:7:\"#markup\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:2153:\"<div id=\"block-pcf-theme-homepageservices-2\">\n  \n    \n      \n  <div>\n    <div>Body</div>\n              <div><section class=\"pcf-services\">\n  <div class=\"pcf-services__inner\">\n    <div class=\"pcf-services__intro\">\n      <h2>What we do</h2>\n      <p>Three core mandates protecting Kenyan policyholders</p>\n    </div>\n    <div class=\"pcf-services__grid\">\n      <div class=\"pcf-service-card\">\n        <div class=\"pcf-service-card__icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M12 2l8 4v6c0 5-3.5 8.5-8 10-4.5-1.5-8-5-8-10V6l8-4z\"/></svg></div>\n        <h3>Compensation</h3>\n        <p>Timely payouts to policyholders of insurers placed under statutory management or whose licence has been cancelled.</p>\n        <a href=\"/compensation\" class=\"pcf-service-card__cta\">Learn more <span aria-hidden=\"true\">→</span></a>\n      </div>\n      <div class=\"pcf-service-card\">\n        <div class=\"pcf-service-card__icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M3 21h18M5 21V7l7-4 7 4v14M9 9h1M9 13h1M9 17h1M14 9h1M14 13h1M14 17h1\"/></svg></div>\n        <h3>Statutory Management</h3>\n        <p>Overseeing distressed insurers to protect policyholder interests during periods of financial instability.</p>\n        <a href=\"/statutory-management\" class=\"pcf-service-card__cta\">Learn more <span aria-hidden=\"true\">→</span></a>\n      </div>\n      <div class=\"pcf-service-card\">\n        <div class=\"pcf-service-card__icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M3 6h18M3 12h18M3 18h18\"/><circle cx=\"6\" cy=\"6\" r=\"1.5\" fill=\"currentColor\" stroke=\"none\"/><circle cx=\"6\" cy=\"12\" r=\"1.5\" fill=\"currentColor\" stroke=\"none\"/><circle cx=\"6\" cy=\"18\" r=\"1.5\" fill=\"currentColor\" stroke=\"none\"/></svg></div>\n        <h3>Liquidation</h3>\n        <p>Managing the orderly wind-down of insolvent insurance companies in line with the Insurance Act.</p>\n        <a href=\"/liquidation\" class=\"pcf-service-card__cta\">Learn more <span aria-hidden=\"true\">→</span></a>\n      </div>\n    </div>\n  </div>\n</section></div>\n          </div>\n\n  </div>\n\";}s:9:\"#attached\";a:0:{}s:6:\"#cache\";a:3:{s:8:\"contexts\";a:4:{i:0;s:28:\"languages:language_interface\";i:1;s:5:\"theme\";i:2;s:16:\"user.permissions\";i:3;s:31:\"route.name.is_layout_builder_ui\";}s:4:\"tags\";a:5:{i:0;s:17:\"config:block_list\";i:1;s:18:\"block_content_view\";i:2;s:15:\"block_content:3\";i:3;s:67:\"config:core.entity_view_display.block_content.homepage_hero.default\";i:4;s:30:\"config:filter.format.full_html\";}s:7:\"max-age\";i:-1;}}',-1,1789287206.202,1,'block_content:3 block_content_view config:block_list config:core.entity_view_display.block_content.homepage_hero.default config:filter.format.full_html rendered','0'),
