('entity_view:block:pcf_theme_homepagestats:[languages:language_interface]=en:[route.name.is_layout_builder_ui]=is_layout_builder_ui.1:[theme]=pcf_theme:[user.permissions]=a89e24af461adc3524902f5a2d219617cd0066ced07fd34ced61ca4b5ef9dcd5','a:3:{s:7:\"#markup\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:3073:\"<div id=\"block-pcf-theme-homepagestats\">\n  \n    \n      \n  <div>\n    <div>Body</div>\n              <div><section class=\"pcf-stats\" style=\"background-image: url(\'/sites/default/files/stats-photo.jpg\');\">\n  <div class=\"pcf-stats__overlay\"></div>\n  <div class=\"pcf-stats__inner\">\n    <div class=\"pcf-stats__intro\">\n      <h2>Our impact so far</h2>\n      <p>Real outcomes for real Kenyan policyholders</p>\n    </div>\n    <div class=\"pcf-stats__grid\">\n      <div class=\"pcf-stat\">\n        <span class=\"pcf-stat__number\" data-target=\"2146\" data-decimals=\"0\" data-prefix=\"\" data-suffix=\"\">0</span>\n        <span class=\"pcf-stat__label\">Claims settled</span>\n      </div>\n      <div class=\"pcf-stat\">\n        <span class=\"pcf-stat__number\" data-target=\"390.8\" data-decimals=\"1\" data-prefix=\"KSh \" data-suffix=\"M\">0</span>\n        <span class=\"pcf-stat__label\">Paid in compensation</span>\n      </div>\n      <div class=\"pcf-stat\">\n        <span class=\"pcf-stat__number\" data-target=\"8\" data-decimals=\"0\" data-prefix=\"\" data-suffix=\"\">0</span>\n        <span class=\"pcf-stat__label\">Insurers resolved</span>\n      </div>\n      <div class=\"pcf-stat\">\n        <span class=\"pcf-stat__number\" data-target=\"14\" data-decimals=\"0\" data-prefix=\"\" data-suffix=\"\">0</span>\n        <span class=\"pcf-stat__label\">Counties reached through PCFMtaani</span>\n      </div>\n    </div>\n    <p class=\"pcf-stats__note\">Figures as of March 31, 2026</p>\n  </div>\n</section>\n\n<script>\n(function () {\n  var counters = document.querySelectorAll(\'.pcf-stat__number\');\n  var animated = false;\n  function animateCounters() {\n    if (animated) return;\n    animated = true;\n    counters.forEach(function (el) {\n      var target = parseFloat(el.getAttribute(\'data-target\'));\n      var decimals = parseInt(el.getAttribute(\'data-decimals\'), 10) || 0;\n      var prefix = el.getAttribute(\'data-prefix\') || \'\';\n      var suffix = el.getAttribute(\'data-suffix\') || \'\';\n      var duration = 1600;\n      var startTime = null;\n      function step(timestamp) {\n        if (!startTime) startTime = timestamp;\n        var progress = Math.min((timestamp - startTime) / duration, 1);\n        var eased = 1 - Math.pow(1 - progress, 3);\n        var current = target * eased;\n        var formatted = decimals > 0 ? current.toFixed(decimals) : Math.floor(current).toLocaleString();\n        el.textContent = prefix + formatted + suffix;\n        if (progress < 1) { requestAnimationFrame(step); }\n        else { var finalFormatted = decimals > 0 ? target.toFixed(decimals) : target.toLocaleString(); el.textContent = prefix + finalFormatted + suffix; }\n      }\n      requestAnimationFrame(step);\n    });\n  }\n  var section = document.querySelector(\'.pcf-stats\');\n  if (section && \'IntersectionObserver\' in window) {\n    var observer = new IntersectionObserver(function (entries) {\n      entries.forEach(function (entry) { if (entry.isIntersecting) { animateCounters(); observer.disconnect(); } });\n    }, { threshold: 0.3 });\n    observer.observe(section);\n  } else { animateCounters(); }\n})();\n</script></div>\n          </div>\n\n  </div>\n\";}s:9:\"#attached\";a:0:{}s:6:\"#cache\";a:3:{s:8:\"contexts\";a:4:{i:0;s:28:\"languages:language_interface\";i:1;s:5:\"theme\";i:2;s:16:\"user.permissions\";i:3;s:31:\"route.name.is_layout_builder_ui\";}s:4:\"tags\";a:5:{i:0;s:17:\"config:block_list\";i:1;s:18:\"block_content_view\";i:2;s:15:\"block_content:4\";i:3;s:67:\"config:core.entity_view_display.block_content.homepage_hero.default\";i:4;s:30:\"config:filter.format.full_html\";}s:7:\"max-age\";i:-1;}}',-1,1789287206.199,1,'block_content:4 block_content_view config:block_list config:core.entity_view_display.block_content.homepage_hero.default config:filter.format.full_html rendered','0'),
