('entity_view:block:pcf_theme_sitefooter:[languages:language_interface]=en:[route.name.is_layout_builder_ui]=is_layout_builder_ui.1:[theme]=pcf_theme:[user.permissions]=a89e24af461adc3524902f5a2d219617cd0066ced07fd34ced61ca4b5ef9dcd5','a:3:{s:7:\"#markup\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:2980:\"<div id=\"block-pcf-theme-sitefooter\">\n  \n    \n      \n  <div>\n    <div>Body</div>\n              <div><footer class=\"pcf-footer\">\n  <div class=\"pcf-footer__inner\">\n    <div class=\"pcf-footer__col pcf-footer__col--about\">\n      <h3>Policyholders Compensation Fund</h3>\n      <p>Upholding public confidence in the insurance sector through timely compensation of claimants and prompt resolution of insurers.</p>\n      <div class=\"pcf-footer__social\">\n        <a href=\"https://facebook.com/PCFKenya\" aria-label=\"Facebook\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M22 12a10 10 0 1 0-11.6 9.9v-7H7.9V12h2.5V9.8c0-2.5 1.5-3.9 3.8-3.9 1.1 0 2.2.2 2.2.2v2.5h-1.3c-1.2 0-1.6.8-1.6 1.6V12h2.8l-.4 2.9h-2.4v7A10 10 0 0 0 22 12z\"/></svg></a>\n        <a href=\"https://x.com/PCF_Kenya\" aria-label=\"X (Twitter)\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M18.9 2H22l-7.2 8.3L23 22h-6.6l-5.2-6.8L5.2 22H2l7.7-8.8L1.6 2h6.8l4.7 6.2L18.9 2zm-1.2 18h1.8L7.4 4H5.5l12.2 16z\"/></svg></a>\n        <a href=\"https://linkedin.com/company/pcfkenya\" aria-label=\"LinkedIn\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4.98 3.5a2.5 2.5 0 1 1 0 5 2.5 2.5 0 0 1 0-5zM3 9h4v12H3V9zm7 0h3.8v1.7h.05c.53-1 1.83-2.05 3.77-2.05C21.5 8.65 22 11 22 14v7h-4v-6.2c0-1.48-.03-3.4-2.07-3.4-2.07 0-2.38 1.62-2.38 3.29V21h-4V9z\"/></svg></a>\n        <a href=\"https://youtube.com/@PCFKenya\" aria-label=\"YouTube\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M23 12s0-3.5-.45-5.2a2.9 2.9 0 0 0-2-2.05C18.9 4.3 12 4.3 12 4.3s-6.9 0-8.55.45a2.9 2.9 0 0 0-2 2.05C1 8.5 1 12 1 12s0 3.5.45 5.2a2.9 2.9 0 0 0 2 2.05C5.1 19.7 12 19.7 12 19.7s6.9 0 8.55-.45a2.9 2.9 0 0 0 2-2.05C23 15.5 23 12 23 12zM9.75 15.5v-7l6 3.5-6 3.5z\"/></svg></a>\n      </div>\n    </div>\n    <div class=\"pcf-footer__col\">\n      <h4>Quick Links</h4>\n      <ul>\n        <li><a href=\"/\">Home</a></li>\n        <li><a href=\"/about-pcf\">About PCF</a></li>\n        <li><a href=\"/what-we-do\">What We Do</a></li>\n        <li><a href=\"/resources\">Resources</a></li>\n        <li><a href=\"/faqs\">FAQs</a></li>\n      </ul>\n    </div>\n    <div class=\"pcf-footer__col\">\n      <h4>Get Help</h4>\n      <ul>\n        <li><a href=\"https://cms.pcf.go.ke/\">File a Claim</a></li>\n        <li><a href=\"https://cms.pcf.go.ke/\">Check Claim Status</a></li>\n        <li><a href=\"/complaints\">Complaints</a></li>\n        <li><a href=\"/report-corruption\">Report Corruption</a></li>\n      </ul>\n    </div>\n    <div class=\"pcf-footer__col\">\n      <h4>Contact Us</h4>\n      <address>KWFT Center, 6th Floor<br>Masaba Road, Upper Hill<br>P.O. Box 24203-00100<br>Nairobi, Kenya</address>\n      <p><a href=\"tel:+254794582700\">+254 794 582 700</a></p>\n      <p><a href=\"mailto:info@pcf.go.ke\">info@pcf.go.ke</a></p>\n    </div>\n  </div>\n  <div class=\"pcf-footer__bottom\">\n    <p>&copy; 2026 Policyholders Compensation Fund. All rights reserved.</p>\n    <p>A State Corporation under the National Treasury</p>\n  </div>\n</footer></div>\n          </div>\n\n  </div>\n\";}s:9:\"#attached\";a:0:{}s:6:\"#cache\";a:3:{s:8:\"contexts\";a:4:{i:0;s:28:\"languages:language_interface\";i:1;s:5:\"theme\";i:2;s:16:\"user.permissions\";i:3;s:31:\"route.name.is_layout_builder_ui\";}s:4:\"tags\";a:5:{i:0;s:17:\"config:block_list\";i:1;s:18:\"block_content_view\";i:2;s:15:\"block_content:7\";i:3;s:67:\"config:core.entity_view_display.block_content.homepage_hero.default\";i:4;s:30:\"config:filter.format.full_html\";}s:7:\"max-age\";i:-1;}}',-1,1789287206.197,1,'block_content:7 block_content_view config:block_list config:core.entity_view_display.block_content.homepage_hero.default config:filter.format.full_html rendered','0'),
('entity_view:block:pcf_theme_sitefooter:[languages:language_interface]=en:[theme]=pcf_theme:[user.permissions]=a89e24af461adc3524902f5a2d219617cd0066ced07fd34ced61ca4b5ef9dcd5','O:31:\"Drupal\\Core\\Cache\\CacheRedirect\":3:{s:16:\"\0*\0cacheContexts\";a:4:{i:0;s:28:\"languages:language_interface\";i:1;s:5:\"theme\";i:2;s:16:\"user.permissions\";i:3;s:31:\"route.name.is_layout_builder_ui\";}s:12:\"\0*\0cacheTags\";a:0:{}s:14:\"\0*\0cacheMaxAge\";i:-1;}',-1,1789287206.197,1,'','0'),
('entity_view:node:10:full:[languages:language_interface]=en:[route.name.is_layout_builder_ui]=is_layout_builder_ui.1:[theme]=pcf_theme:[timezone]=Etc/UTC:[url.site]=https://improved-broccoli-pw4qxv69gw6c7pgq-8443.vOPzc7IkRpqTQ7KHV9Oe3c3vQAQgpoufJRwIKBDsNeU','a:5:{s:7:\"#markup\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:4455:\"<article>\n\n  \n    \n\n  \n  <div>\n      <div class=\"layout layout--onecol\">\n    <div  class=\"layout__region layout__region--content\">\n      <div>\n  \n    \n      \n            <div><section class=\"pcf-page-hero\">\n  <div class=\"pcf-page-hero__inner\">\n    <div class=\"pcf-page-hero__breadcrumb\"><a href=\"/\">Home</a> / About PCF / Management</div>\n    <h1>Management</h1>\n    <p>The Fund\'s day-to-day operations are led by a management team responsible for implementing the Board\'s strategy and policies.</p>\n  </div>\n</section>\n\n<div class=\"pcf-board\">\n  <div class=\"pcf-board__inner\">\n\n    <div class=\"pcf-board-grid\">\n\n      <div class=\"pcf-board-card\">\n        <div class=\"pcf-board-card__photo\">\n          <img src=\"/sites/default/files/management/mohamed-sahal.jpg\" alt=\"Mr. Mohamed Sahal\" onerror=\"this.style.display=\'none\'; this.nextElementSibling.style.display=\'flex\';\">\n          <div class=\"pcf-board-card__initials\" style=\"display:none;\">MS</div>\n        </div>\n        <h3>Mr. Mohamed Sahal</h3>\n        <p class=\"pcf-board-card__role\">Managing Trustee &amp; Chief Executive Officer</p>\n        <div class=\"pcf-board-card__bio\">\n          <p>Provides strategic leadership over the Fund\'s operations, overseeing compensation, statutory management, liquidation, and policy advisory to the National Treasury on matters relating to policyholder protection.</p>\n        </div>\n      </div>\n\n      <div class=\"pcf-board-card\">\n        <div class=\"pcf-board-card__photo\">\n          <img src=\"/sites/default/files/management/james-njogu.jpg\" alt=\"Mr. James Njogu\" onerror=\"this.style.display=\'none\'; this.nextElementSibling.style.display=\'flex\';\">\n          <div class=\"pcf-board-card__initials\" style=\"display:none;\">JN</div>\n        </div>\n        <h3>Mr. James Njogu</h3>\n        <p class=\"pcf-board-card__role\">Director, Legal Services</p>\n        <div class=\"pcf-board-card__bio\">\n          <p>An Advocate of the High Court of Kenya, Company Secretary, and Arbitrator &amp; Mediator, overseeing the Fund\'s legal affairs and corporate governance.</p>\n        </div>\n      </div>\n\n      <div class=\"pcf-board-card\">\n        <div class=\"pcf-board-card__photo\">\n          <img src=\"/sites/default/files/management/abudo-mamo.jpg\" alt=\"Mr. Abudo Qonchoro Mamo\" onerror=\"this.style.display=\'none\'; this.nextElementSibling.style.display=\'flex\';\">\n          <div class=\"pcf-board-card__initials\" style=\"display:none;\">AM</div>\n        </div>\n        <h3>Mr. Abudo Qonchoro Mamo</h3>\n        <p class=\"pcf-board-card__role\">Director, Corporate Services</p>\n        <div class=\"pcf-board-card__bio\">\n          <p>Oversees the Fund\'s corporate services function, supporting the organization\'s operational and administrative infrastructure.</p>\n        </div>\n      </div>\n\n      <div class=\"pcf-board-card\">\n        <div class=\"pcf-board-card__photo\">\n          <img src=\"/sites/default/files/management/noel-zuma.jpg\" alt=\"Mr. Noel Ngome Zuma\" onerror=\"this.style.display=\'none\'; this.nextElementSibling.style.display=\'flex\';\">\n          <div class=\"pcf-board-card__initials\" style=\"display:none;\">NZ</div>\n        </div>\n        <h3>Mr. Noel Ngome Zuma</h3>\n        <p class=\"pcf-board-card__role\">Director, Compensation and Insurance Risk Monitoring</p>\n        <div class=\"pcf-board-card__bio\">\n          <p>Oversees the Fund\'s compensation processes and monitors the risk profile of licensed insurers.</p>\n        </div>\n      </div>\n\n      <div class=\"pcf-board-card\">\n        <div class=\"pcf-board-card__photo\">\n          <img src=\"/sites/default/files/management/martin-kamau.jpg\" alt=\"Mr. Martin M. Kamau N.\" onerror=\"this.style.display=\'none\'; this.nextElementSibling.style.display=\'flex\';\">\n          <div class=\"pcf-board-card__initials\" style=\"display:none;\">MK</div>\n        </div>\n        <h3>Mr. Martin M. Kamau N.</h3>\n        <p class=\"pcf-board-card__role\">Deputy Director, Internal Audit</p>\n        <div class=\"pcf-board-card__bio\">\n          <p>Leads the Fund\'s internal audit function, providing independent assurance over financial and operational controls.</p>\n        </div>\n      </div>\n\n    </div>\n\n    <div class=\"pcf-board__note\">\n      <p>PCF\'s management structure also includes directorates for Statutory Management &amp; Liquidation, Supply Chain Management, and Research, Strategy &amp; Planning, supporting the Fund\'s core mandate.</p>\n    </div>\n\n  </div>\n</div></div>\n      \n  </div>\n\n    </div>\n  </div>\n\n  </div>\n\n</article>\n\";}s:9:\"#attached\";a:2:{s:14:\"html_head_link\";a:2:{i:0;a:1:{i:0;a:2:{s:3:\"rel\";s:9:\"canonical\";s:4:\"href\";s:73:\"https://improved-broccoli-pw4qxv69gw6c7pgq-8443.app.github.dev/management\";}}i:1;a:1:{i:0;a:2:{s:3:\"rel\";s:9:\"shortlink\";s:4:\"href\";s:70:\"https://improved-broccoli-pw4qxv69gw6c7pgq-8443.app.github.dev/node/10\";}}}s:7:\"library\";a:1:{i:0;s:23:\"layout_discovery/onecol\";}}s:6:\"#cache\";a:3:{s:8:\"contexts\";a:6:{i:0;s:31:\"route.name.is_layout_builder_ui\";i:1;s:8:\"url.site\";i:2;s:28:\"languages:language_interface\";i:3;s:5:\"theme\";i:4;s:16:\"user.permissions\";i:5;s:8:\"timezone\";}s:4:\"tags\";a:5:{i:0;s:9:\"node_view\";i:1;s:7:\"node:10\";i:2;s:49:\"config:core.entity_view_display.node.page.default\";i:3;s:30:\"config:filter.format.full_html\";i:4;s:6:\"user:1\";}s:7:\"max-age\";i:-1;}s:17:\"#cache_properties\";a:1:{i:0;s:6:\"#title\";}s:6:\"#title\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:25:\"\n<span>Management</span>\n\";}}',-1,1789401734.615,1,'config:core.entity_view_display.node.page.default config:filter.format.full_html node:10 node_view rendered user:1','0'),
('entity_view:node:10:full:[languages:language_interface]=en:[route.name.is_layout_builder_ui]=is_layout_builder_ui.1:[theme]=pcf_theme:[url.site]=https://improved-broccoli-pw4qxv69gw6c7pgq-8443.app.github.dev:[useWAmhaRNPZGuT9ItwKnD2DA0gqtkatAwqxGmNp3CXBAc','O:31:\"Drupal\\Core\\Cache\\CacheRedirect\":3:{s:16:\"\0*\0cacheContexts\";a:6:{i:0;s:31:\"route.name.is_layout_builder_ui\";i:1;s:8:\"url.site\";i:2;s:28:\"languages:language_interface\";i:3;s:5:\"theme\";i:4;s:16:\"user.permissions\";i:5;s:8:\"timezone\";}s:12:\"\0*\0cacheTags\";a:0:{}s:14:\"\0*\0cacheMaxAge\";i:-1;}',-1,1789401734.615,1,'','0'),
('entity_view:node:11:full:[languages:language_interface]=en:[route.name.is_layout_builder_ui]=is_layout_builder_ui.1:[theme]=pcf_theme:[timezone]=Etc/UTC:[url.site]=https://improved-broccoli-pw4qxv69gw6c7pgq-8443.MsqlK-YvHe1n8cPKobTl5pAtyN-dMJeqBG_EuEPtq78','a:5:{s:7:\"#markup\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:4168:\"<article>\n\n  \n    \n\n  \n  <div>\n      <div class=\"layout layout--onecol\">\n    <div  class=\"layout__region layout__region--content\">\n      <div>\n  \n    \n      \n            <div><section class=\"pcf-page-hero\">\n  <div class=\"pcf-page-hero__inner\">\n    <div class=\"pcf-page-hero__breadcrumb\"><a href=\"/\">Home</a> / About PCF / Stakeholders</div>\n    <h1>Stakeholders</h1>\n    <p>PCF works alongside policyholders, insurers, and industry partners to protect the interests of the insuring public.</p>\n  </div>\n</section>\n\n<div class=\"pcf-stakeholders\">\n  <div class=\"pcf-stakeholders__inner\">\n\n    <div class=\"pcf-stakeholder-card\">\n      <div class=\"pcf-stakeholder-card__icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM4 21c0-4 3.5-7 8-7s8 3 8 7\"/></svg>\n      </div>\n      <h3>Policyholder</h3>\n      <ul>\n        <li>The Fund\'s primary mandate is the payment of compensation to policyholders of insurance companies that have been declared insolvent — policyholders are therefore the primary beneficiaries of the Fund.</li>\n        <li>Policyholders pay into the Fund a levy equivalent to 0.25% of their premiums, making them contributors as well as beneficiaries.</li>\n      </ul>\n    </div>\n\n    <div class=\"pcf-stakeholder-card\">\n      <div class=\"pcf-stakeholder-card__icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M3 21h18M5 21V7l7-4 7 4v14M9 9h1M9 13h1M9 17h1M14 9h1M14 13h1M14 17h1\"/></svg>\n      </div>\n      <h3>Insurance Companies</h3>\n      <ul>\n        <li>Issue clients with policies that form the basis of claims settlements and, in the event of insolvency, the basis of the compensation amount payable.</li>\n        <li>Contribute to the Fund through a levy equivalent to <strong>0.25%</strong> of their premium receipts.</li>\n        <li>Benefit from the increased policyholder confidence the Fund creates, contributing to the stability and growth of the sector.</li>\n        <li>Appoint two representatives to sit on the Fund\'s Board of Trustees.</li>\n      </ul>\n    </div>\n\n    <div class=\"pcf-stakeholder-card pcf-stakeholder-card--wide\">\n      <div class=\"pcf-stakeholder-card__icon\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM23 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n      </div>\n      <h3>Insurance Service Providers</h3>\n      <div class=\"pcf-stakeholder-subgrid\">\n        <div class=\"pcf-stakeholder-sub\">\n          <h4>1. Brokers</h4>\n          <ul>\n            <li>An Insurance Broker represents the interests of the policyholder, ensuring they receive a fair deal from the Insurance Company.</li>\n            <li>As representatives of policyholders, they have an in-depth understanding of their needs and are important partners to the Fund.</li>\n            <li>Insurance brokers appoint one representative to sit on the Fund\'s Board of Trustees.</li>\n          </ul>\n        </div>\n        <div class=\"pcf-stakeholder-sub\">\n          <h4>2. Loss Adjusters</h4>\n          <ul>\n            <li>Surveyors appointed by Insurance companies to independently assess, qualify, and report on the actual loss or damage, quantifying the claim payable under the policy — for purposes of avoiding false claims.</li>\n            <li>Serve as a link between the insurer and the insured, usually functioning only in non-life business.</li>\n          </ul>\n        </div>\n        <div class=\"pcf-stakeholder-sub\">\n          <h4>3. Agents</h4>\n          <ul>\n            <li>Licensed intermediaries who sell and service insurance policies on behalf of insurance companies.</li>\n          </ul>\n        </div>\n        <div class=\"pcf-stakeholder-sub\">\n          <h4>4. The Government</h4>\n          <ul>\n            <li>Provides the legal and regulatory framework within which the Fund and the insurance industry operate.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</div></div>\n      \n  </div>\n\n    </div>\n  </div>\n\n  </div>\n\n</article>\n\";}s:9:\"#attached\";a:2:{s:14:\"html_head_link\";a:2:{i:0;a:1:{i:0;a:2:{s:3:\"rel\";s:9:\"canonical\";s:4:\"href\";s:75:\"https://improved-broccoli-pw4qxv69gw6c7pgq-8443.app.github.dev/stakeholders\";}}i:1;a:1:{i:0;a:2:{s:3:\"rel\";s:9:\"shortlink\";s:4:\"href\";s:70:\"https://improved-broccoli-pw4qxv69gw6c7pgq-8443.app.github.dev/node/11\";}}}s:7:\"library\";a:1:{i:0;s:23:\"layout_discovery/onecol\";}}s:6:\"#cache\";a:3:{s:8:\"contexts\";a:6:{i:0;s:31:\"route.name.is_layout_builder_ui\";i:1;s:8:\"url.site\";i:2;s:28:\"languages:language_interface\";i:3;s:5:\"theme\";i:4;s:16:\"user.permissions\";i:5;s:8:\"timezone\";}s:4:\"tags\";a:5:{i:0;s:9:\"node_view\";i:1;s:7:\"node:11\";i:2;s:49:\"config:core.entity_view_display.node.page.default\";i:3;s:30:\"config:filter.format.full_html\";i:4;s:6:\"user:1\";}s:7:\"max-age\";i:-1;}s:17:\"#cache_properties\";a:1:{i:0;s:6:\"#title\";}s:6:\"#title\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:27:\"\n<span>Stakeholders</span>\n\";}}',-1,1789401756.457,1,'config:core.entity_view_display.node.page.default config:filter.format.full_html node:11 node_view rendered user:1','0'),
('entity_view:node:11:full:[languages:language_interface]=en:[route.name.is_layout_builder_ui]=is_layout_builder_ui.1:[theme]=pcf_theme:[url.site]=https://improved-broccoli-pw4qxv69gw6c7pgq-8443.app.github.dev:[usezbyNa1vhf0qGaJtKJM2onUUstgiwkBCJ5vg8-AQyDNo','O:31:\"Drupal\\Core\\Cache\\CacheRedirect\":3:{s:16:\"\0*\0cacheContexts\";a:6:{i:0;s:31:\"route.name.is_layout_builder_ui\";i:1;s:8:\"url.site\";i:2;s:28:\"languages:language_interface\";i:3;s:5:\"theme\";i:4;s:16:\"user.permissions\";i:5;s:8:\"timezone\";}s:12:\"\0*\0cacheTags\";a:0:{}s:14:\"\0*\0cacheMaxAge\";i:-1;}',-1,1789401756.457,1,'','0'),
('entity_view:node:12:full:[languages:language_interface]=en:[route.name.is_layout_builder_ui]=is_layout_builder_ui.1:[theme]=pcf_theme:[timezone]=Etc/UTC:[url.site]=https://improved-broccoli-pw4qxv69gw6c7pgq-8443.pB0MqIE62HeW-6PTw5fzWH-oy4nhOZmWAvidXzyZuUs','a:5:{s:7:\"#markup\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:12471:\"<article>\n\n  \n    \n\n  \n  <div>\n      <div class=\"layout layout--onecol\">\n    <div  class=\"layout__region layout__region--content\">\n      <div>\n  \n    \n      \n            <div><section class=\"pcf-page-hero\">\n  <div class=\"pcf-page-hero__inner\">\n    <div class=\"pcf-page-hero__breadcrumb\"><a href=\"/\">Home</a> / About PCF / Service Delivery Charter</div>\n    <h1>Citizens\' Service Delivery Charter</h1>\n    <p>Our commitment to courtesy and excellence in service delivery — what to expect, and how long it takes.</p>\n    <div class=\"pcf-lang-toggle\">\n      <button type=\"button\" class=\"pcf-lang-btn pcf-lang-btn--active\" data-lang=\"en\">English</button>\n      <button type=\"button\" class=\"pcf-lang-btn\" data-lang=\"sw\">Kiswahili</button>\n    </div>\n  </div>\n</section>\n\n<div class=\"pcf-charter\" id=\"lang-en\">\n  <div class=\"pcf-charter__inner\">\n\n    <div class=\"pcf-charter__table-wrap\">\n      <table class=\"pcf-charter__table\">\n        <thead>\n          <tr>\n            <th>#</th>\n            <th>Customer Support Service</th>\n            <th>Customer Requirement(s)</th>\n            <th>Cost of Service</th>\n            <th>Timeline</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>1</td><td>Response to phone calls (landline or any other official line)</td><td>Phone call</td><td class=\"pcf-charter__free\">Free</td><td>15 seconds</td></tr>\n          <tr><td>2</td><td>Response to enquiry by walk-in clients</td><td>Walk-in and make the enquiry</td><td class=\"pcf-charter__free\">Free</td><td>1 minute</td></tr>\n          <tr><td>3</td><td>Response to correspondences</td><td>Written correspondence (letters)</td><td class=\"pcf-charter__free\">Free</td><td>5 working days</td></tr>\n          <tr><td></td><td></td><td>Email and social media (X, Facebook &amp; YouTube)</td><td class=\"pcf-charter__free\">Free</td><td>1 working day</td></tr>\n          <tr><td>4</td><td>Response to public complaints and grievances</td><td>Make a complaint</td><td class=\"pcf-charter__free\">Free</td><td>1 working day</td></tr>\n          <tr><td>5</td><td>Resolution of complaints</td><td>Make a verbal or written complaint</td><td class=\"pcf-charter__free\">Free</td><td>14 working days</td></tr>\n          <tr><td>6</td><td>Compensation of claimants</td><td>Duly filled compensation claim form with prescribed supporting documentation</td><td class=\"pcf-charter__free\">Free</td><td>90 working days from date of receipt</td></tr>\n          <tr><td>7</td><td>Statutory Management Services</td><td>Appointment letter by Insurance Regulatory Authority</td><td class=\"pcf-charter__negotiated\">As negotiated with the appointing authority</td><td>Within 365 days after appointment</td></tr>\n          <tr><td>8</td><td>Liquidate Insurance Companies</td><td>Appointment by court order</td><td class=\"pcf-charter__negotiated\">As negotiated with the appointing authority</td><td>Process commences within 24 hours of appointment</td></tr>\n          <tr><td>9</td><td>Receipt of Levy</td><td>Attach evidence of payment</td><td class=\"pcf-charter__free\">Free</td><td>1 working day</td></tr>\n          <tr><td>10</td><td>Registration of suppliers</td><td>Duly filled application, company profile, certificates, tax compliance, bank statement, and supporting documents</td><td class=\"pcf-charter__free\">Free</td><td>14 working days</td></tr>\n          <tr><td>11</td><td>Processing of tenders</td><td>Submission of bids for goods and services</td><td class=\"pcf-charter__free\">Free</td><td>90 working days from bid submission</td></tr>\n          <tr><td>12</td><td>Notification of successful and unsuccessful bidders</td><td>Access e-procurement portal for notification</td><td class=\"pcf-charter__free\">Free</td><td>1 working day from bid evaluation</td></tr>\n          <tr><td>13</td><td>Payment of goods and services received</td><td>LPO / Invoice / Certificate of Completion or Goods/Services received</td><td class=\"pcf-charter__free\">Free</td><td>30 working days from receipt of invoice</td></tr>\n          <tr><td>14</td><td>Disposal of obsolete stores</td><td>Submission of bids</td><td class=\"pcf-charter__free\">Free</td><td>60 working days from date of advertisement</td></tr>\n          <tr><td>15</td><td>Public participation in policy-making process</td><td>Familiarization with issues and active participation</td><td class=\"pcf-charter__free\">Free</td><td>1 working day</td></tr>\n          <tr><td>16</td><td>Recruitment of staff</td><td>Make a formal application based on the advert</td><td class=\"pcf-charter__free\">Free</td><td>90 working days</td></tr>\n          <tr><td>17</td><td>Processing of request for information</td><td>Make a request for information</td><td class=\"pcf-charter__free\">Free</td><td>21 working days</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <div class=\"pcf-charter__banner\">\n      <p>PCF is committed to courtesy and excellence in service delivery</p>\n    </div>\n\n    <div class=\"pcf-charter__escalation\">\n      <h3>Not satisfied with the service you received?</h3>\n      <p>Any service that does not conform to the above standards, or any officer who does not live up to these commitments, should be reported to:</p>\n      <div class=\"pcf-charter__escalation-grid\">\n        <div class=\"pcf-info-box\">\n          <h4>The Managing Trustee</h4>\n          <p>Policyholders Compensation Fund<br>KWFT Centre, 6th Floor, Masaba–Kiambere Road<br>P.O. Box 24203-00100, Nairobi</p>\n          <p><a href=\"tel:+254794582700\">0794 582 700</a> / <a href=\"tel:0111121700\">011 1121700</a></p>\n          <p><a href=\"mailto:info@pcf.go.ke\">info@pcf.go.ke</a> · <a href=\"mailto:complaints@pcf.go.ke\">complaints@pcf.go.ke</a></p>\n        </div>\n        <div class=\"pcf-info-box\">\n          <h4>The Commission Secretary / CEO</h4>\n          <p>Commission on Administrative Justice<br>2nd Floor, West End Towers, off Waiyaki Way<br>P.O. Box 20414-00200, Nairobi</p>\n          <p><a href=\"tel:+254202270000\">020 2270000</a> / 2303000 / 2603765</p>\n          <p><a href=\"mailto:info@ombudsman.go.ke\">info@ombudsman.go.ke</a></p>\n        </div>\n      </div>\n    </div>\n\n    <p class=\"pcf-charter__motto\">\"Huduma Bora, Ni Haki Yako\"</p>\n\n  </div>\n</div>\n\n<div class=\"pcf-charter\" id=\"lang-sw\" style=\"display:none;\">\n  <div class=\"pcf-charter__inner\">\n\n    <div class=\"pcf-charter__table-wrap\">\n      <table class=\"pcf-charter__table\">\n        <thead>\n          <tr>\n            <th>Na</th>\n            <th>Huduma Saidizi kwa Mteja</th>\n            <th>(Ma)Hitaji ya Mteja</th>\n            <th>Gharama ya Huduma</th>\n            <th>Muda wa Kutekeleza</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr><td>1</td><td>Kujibu simu (simu rasmi ya ofisi)</td><td>Kupiga simu</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Sekunde 15</td></tr>\n          <tr><td>2</td><td>Kujibu maswali ya wateja wanaotembelea ofisi ana kwa ana</td><td>Tembelea ofisi na kuuliza swali</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Dakika 1</td></tr>\n          <tr><td>3</td><td>Majibu kwa mawasiliano</td><td>Kuwasiliana kimaandishi (Barua)</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 5 za kazi</td></tr>\n          <tr><td></td><td></td><td>Barua-pepe na mitandao ya kijamii (Twita, Facebook, YouTube)</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 1 ya kazi</td></tr>\n          <tr><td>4</td><td>Majibu kwa malalamiko na utetezi wa umma</td><td>Wasilisha malalamiko</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 1 ya kazi</td></tr>\n          <tr><td>5</td><td>Utatuzi wa malalamiko</td><td>Wasilisha malalamiko kimaandishi au kimazungumzo</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 14 za kazi</td></tr>\n          <tr><td>6</td><td>Kufidia walalamishi</td><td>Fomu ya madai ya fidia iliyojazwa ipasavyo na kuwasilishwa pamoja na hati za kuunga mkono</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 90 za kazi baada ya tarehe ya kupokea ombi la fidia</td></tr>\n          <tr><td>7</td><td>Huduma za usimamizi wa kisheria</td><td>Barua ya uteuzi kutoka kwa Mamlaka ya Udhibiti wa Bima</td><td class=\"pcf-charter__negotiated\">Kama ilivyojadiliwa na mamlaka ya uteuzi</td><td>Ndani ya siku 365 baada ya uteuzi</td></tr>\n          <tr><td>8</td><td>Kufilisi bima</td><td>Uteuzi kwa amri ya mahakama</td><td class=\"pcf-charter__negotiated\">Kama ilivyojadiliwa na mamlaka ya uteuzi</td><td>Mchakato unaanza ndani ya saa 24 baada ya uteuzi</td></tr>\n          <tr><td>9</td><td>Stakabadhi ya Kampuni ya Ushuru</td><td>Ambatanisha ushahidi wa malipo</td><td class=\"pcf-charter__negotiated\">Kama ilivyojadiliwa na mamlaka ya uteuzi</td><td>Siku 1 ya kazi</td></tr>\n          <tr><td>10</td><td>Kusajili wasambazaji</td><td>Kujaza ipasavyo fomu ya maombi, wasifu wa kampuni, vyeti, uzingatiaji ushuru, taarifa ya benki na hati zinazohitajika</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 14 za kazi</td></tr>\n          <tr><td>11</td><td>Kushughulikia zabuni</td><td>Zabuni za uwasilishaji bidhaa na huduma</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 90 baada ya kuwasilisha zabuni</td></tr>\n          <tr><td>12</td><td>Taarifa ya wazabuni waliofaulu na ambao hawajafaulu</td><td>Fikia tovuti ya ununuzi wa kielektroniki kwa taarifa</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 1 baada ya kutathmini zabuni</td></tr>\n          <tr><td>13</td><td>Malipo ya bidhaa na huduma zilizopokelewa</td><td>Agizo la Ununuzi wa Ndani (L.P.O) / Cheti cha ankara cha kukamilisha bidhaa/huduma zilizopokelewa</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 30 za kazi baada ya tarehe ya kupokea ombi</td></tr>\n          <tr><td>14</td><td>Kuuza bidhaa zisizohitajika</td><td>Uwasilishaji wa zabuni</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 60 za kazi baada ya kupokea zabuni</td></tr>\n          <tr><td>15</td><td>Kushiriki kwa umma katika mchakato wa uundaji sera</td><td>Kufahamu maswala na kushiriki kikamilifu</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 1 ya kazi</td></tr>\n          <tr><td>16</td><td>Kuajiri wafanyakazi</td><td>Fanya ombi rasmi kulingana na tangazo</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 90 za kazi</td></tr>\n          <tr><td>17</td><td>Kushughulikia ombi la habari</td><td>Wasilisha ombi la habari</td><td class=\"pcf-charter__free\">Bila malipo</td><td>Siku 21 za kazi</td></tr>\n        </tbody>\n      </table>\n    </div>\n\n    <div class=\"pcf-charter__banner\">\n      <p>PCF imejitolea kwa adabu na ubora katika utoaji huduma</p>\n    </div>\n\n    <div class=\"pcf-charter__escalation\">\n      <h3>Hukuridhika na huduma uliyopokea?</h3>\n      <p>Huduma yoyote inayotolewa ambayo haiambatani na viwango vilivyo hapo juu, au afisa yeyote ambaye hatimizi ahadi za uungwana na ubora katika utoaji huduma, anapaswa kuripotiwa kwa:</p>\n      <div class=\"pcf-charter__escalation-grid\">\n        <div class=\"pcf-info-box\">\n          <h4>Mdhamini Mkuu</h4>\n          <p>Hazina ya Fidia kwa Wenye-Hisa<br>Kituo cha KWFT, Ghorofa ya 6, Barabara ya Masaba-Kiambere<br>Sanduku la Posta 24203-00100, Nairobi</p>\n          <p><a href=\"tel:+254794582700\">0794 582 700</a> / <a href=\"tel:0111121700\">011 1121700</a></p>\n          <p><a href=\"mailto:info@pcf.go.ke\">info@pcf.go.ke</a> · <a href=\"mailto:complaints@pcf.go.ke\">complaints@pcf.go.ke</a></p>\n        </div>\n        <div class=\"pcf-info-box\">\n          <h4>Katibu wa Tume / Mkurugenzi Mtendaji</h4>\n          <p>Tume ya Haki ya Utawala<br>Ghorofa ya 2, West End Towers, nje ya Barabara ya Waiyaki<br>Sanduku la Posta 20414-00200, Nairobi</p>\n          <p><a href=\"tel:+254202270000\">020 2270000</a> / 2303000 / 2603765</p>\n          <p><a href=\"mailto:info@ombudsman.go.ke\">info@ombudsman.go.ke</a></p>\n        </div>\n      </div>\n    </div>\n\n    <p class=\"pcf-charter__motto\">\"Huduma Bora, Ni Haki Yako\"</p>\n\n  </div>\n</div>\n\n<script>\n(function () {\n  var buttons = document.querySelectorAll(\'.pcf-lang-btn\');\n  buttons.forEach(function (btn) {\n    btn.addEventListener(\'click\', function () {\n      buttons.forEach(function (b) { b.classList.remove(\'pcf-lang-btn--active\'); });\n      btn.classList.add(\'pcf-lang-btn--active\');\n      document.getElementById(\'lang-en\').style.display = btn.dataset.lang === \'en\' ? \'block\' : \'none\';\n      document.getElementById(\'lang-sw\').style.display = btn.dataset.lang === \'sw\' ? \'block\' : \'none\';\n    });\n  });\n})();\n</script></div>\n      \n  </div>\n\n    </div>\n  </div>\n\n  </div>\n\n</article>\n\";}s:9:\"#attached\";a:2:{s:14:\"html_head_link\";a:2:{i:0;a:1:{i:0;a:2:{s:3:\"rel\";s:9:\"canonical\";s:4:\"href\";s:87:\"https://improved-broccoli-pw4qxv69gw6c7pgq-8443.app.github.dev/service-delivery-charter\";}}i:1;a:1:{i:0;a:2:{s:3:\"rel\";s:9:\"shortlink\";s:4:\"href\";s:70:\"https://improved-broccoli-pw4qxv69gw6c7pgq-8443.app.github.dev/node/12\";}}}s:7:\"library\";a:1:{i:0;s:23:\"layout_discovery/onecol\";}}s:6:\"#cache\";a:3:{s:8:\"contexts\";a:6:{i:0;s:31:\"route.name.is_layout_builder_ui\";i:1;s:8:\"url.site\";i:2;s:28:\"languages:language_interface\";i:3;s:5:\"theme\";i:4;s:16:\"user.permissions\";i:5;s:8:\"timezone\";}s:4:\"tags\";a:5:{i:0;s:9:\"node_view\";i:1;s:7:\"node:12\";i:2;s:49:\"config:core.entity_view_display.node.page.default\";i:3;s:30:\"config:filter.format.full_html\";i:4;s:6:\"user:1\";}s:7:\"max-age\";i:-1;}s:17:\"#cache_properties\";a:1:{i:0;s:6:\"#title\";}s:6:\"#title\";O:25:\"Drupal\\Core\\Render\\Markup\":1:{s:9:\"\0*\0string\";s:39:\"\n<span>Service Delivery Charter</span>\n\";}}',-1,1789401796.683,1,'config:core.entity_view_display.node.page.default config:filter.format.full_html node:12 node_view rendered user:1','0'),
